import { toRaw } from 'vue';
import { defineStore } from 'pinia';
import { dynamicObj } from './../../pages/assets';
import { supplierApiService } from 'src/services';
import { removeSortOrderFromStorage } from 'src/utils/ms_utlis';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { masterDataPrefix, supplier_dashboard_columns } from 'src/constants';
import { supplierGroupOptions } from 'src/supplier/constant';

export const useDashboardSupplierStore = defineStore(
  'dashboard_supplier_store',
  {
    state: () => ({
      paginationCount: 0,
      current_supplier: 0,
      total_supplier_count: 0,
      pending_supplier: {} as dynamicObj,
      loading: true,
      pending_approval_supplier: 0,
      pending_registration_supplier: 0,
      quickFilterMap: new Map<string, any>(),
      display_data: [] as dynamicObj[],
      expiredCount: {} as any,
      additionalFields: {} as dynamicObj,
      supplierOptionList: supplierGroupOptions,
      supplierStatusList: [] as dynamicObj[],
      visible_columns: {} as dynamicObj,
      filter: {
        supplier_group: '',
        status: '',
        date_added: '',
        location: '',
        search: '',
        zip_code: '',
        insurance_expired: 0,
      } as dynamicObj,
      pagination: {
        current_page: 1,
        total_pages: 0,
        page_size: 25,
      },
      data: {} as Record<string, any>,
      order_by: {} as dynamicObj,
      sortby_data_types: {} as Record<string, any>,
      supplier_status: '',
      table_columns: {
        supplier_name: {
          name: 'sh.supplier_name',
          translation_key: 'supplier_name',
          actions: true,
          field: 'supplier_name',
          order: 0,
        },
        supplier_alias: {
          name: 'supplier_alias',
          translation_key: 'supplier_alias',
          actions: true,
          field: 'supplier_alias',
          order: 1,
        },
        supplier_number: {
          name: 'supplier_number',
          translation_key: 'supplier_number',
          actions: true,
          field: 'supplier_number',
          order: 2,
        },
        supplier_type: {
          name: 'socu.supplier_type',
          translation_key: 'supplier_groups',
          actions: true,
          field: 'supplier_type',
          order: 3,
        },
        status: {
          name: 'socu.status',
          translation_key: 'supplier_status',
          actions: true,
          field: 'status',
          order: 4,
        },
        referrer_name: {
          name: 'socu.referrer_name',
          translation_key: 'referrer',
          actions: true,
          field: 'referrer_name',
          order: 5,
        },
        responder_first_name: {
          name: 'responder_first_name',
          translation_key: 'supplier_responder_first_name',
          actions: true,
          field: 'responder_first_name',
          order: 6,
        },
        responder_name: {
          name: 'responder_name',
          translation_key: 'supplier_responder_last_name',
          actions: true,
          field: 'responder_name',
          order: 7,
        },
        responder_email: {
          name: 'socu.responder_email',
          translation_key: 'supplier_responder_email',
          actions: true,
          field: 'responder_email',
          order: 8,
        },
        created_on: {
          name: 'created_on',
          translation_key: 'log_created_on',
          actions: true,
          field: 'created_on',
          order: 9,
        },
        last_modified_on: {
          name: 'last_modified_on',
          translation_key: 'updated_at',
          actions: true,
          field: 'last_modified_on',
          order: 9,
        },
      } as dynamicObj,
      created_dialog: false,
    }),
    actions: {
      resetPagination() {
        this.pagination = {
          current_page: 1,
          total_pages: 0,
          page_size: this.pagination.page_size,
        };
      },
      toggleCreatedDialog() {
        this.created_dialog = !this.created_dialog;
      },
      resetFilter() {
        this.filter = {
          supplier_group: '',
          status: '',
          date_added: '',
          location: '',
          search: '',
          zip_code: '',
          insurance_expired: 0,
        };
        this.resetPagination();
        removeSortOrderFromStorage('supplier');
        this.sortby_data_types['supplier'].orderByMap = new Map();
        this.quickFilterMap.clear();
      },
      getLabelForFilter(key: string, value: string): string {
        switch (key) {
          case 'supplier_group':
            return (
              this.supplierOptionList.find((item) => item.value === value)
                ?.label || key
            );
          case 'status':
            return (
              this.supplierStatusList.find((item) => item.value === value)
                ?.label || key
            );
          // add more cases as needed
          default:
            return key;
        }
      },

      async getSupplierData() {
        this.loading = true;
        try {
          const filterObj: any = {};
          this.quickFilterMap.clear(); // Clear existing filters
          for (const [key, value] of Object.entries(this.filter)) {
            const data = value;
            if (typeof data === 'object') {
              if (data && Object.keys(data).length > 0) {
                filterObj[key] = (data as any).value;
                this.quickFilterMap.set(key, {
                  label: key,
                  value: (data as any).label,
                });
              }
            } else if (data !== '' && data !== 0) {
              filterObj[key] = data;
              this.quickFilterMap.set(key, {
                label: key,
                value: (data as any).label ?? data,
              });
            }
          }

          const sort = this.sortby_data_types['supplier']?.orderByMap as | Map<string, string> | undefined;
          const sortObj: Array<{ field: string; direction: string }> = [];
          if (sort) {
            for (const [key, value] of sort) {
              sortObj.push({ field: key, direction: value });
            }
          }
          const offset =
            (this.pagination.current_page - 1) * this.pagination.page_size;
          const response = await supplierApiService.supplier_dashboard({
            sort_order_json: JSON.stringify(sortObj),
            ...filterObj,
            limit: this.pagination.page_size,
            skip: offset,
          });
          const countExpired =
            await supplierApiService.get_supplier_expiration_count_dashboard();
          if (!response) throw response;

          this.expiredCount = countExpired.data;
          this.pagination.total_pages = Math.ceil(
            response.metadata.total_results / this.pagination.page_size,
          );
          this.current_supplier = response.metadata.total_results;
          this.display_data = response.data;
          this.paginationCount = response.metadata.total_results;
          this.pending_approval_supplier = response.metadata.pending_count;
          this.total_supplier_count = response.metadata.total_supplier_count;
          this.pending_registration_supplier =
            response.metadata.pending_registration_count;
        } catch (error) {
          this.loading = false;
          throw error;
        }
        this.loading = false;
      },

      async getColumnPreference(master_lookup_type: string) {
        const key = masterDataPrefix + master_lookup_type.toUpperCase();
        const settings_store = useSettingStore();
        const setting = await settings_store.getSetting(key) as dynamicObj;
        return String(!setting ? '[]' : setting);
      },

      async getSavedColumns() {
        try {
          const saved_columns = await this.getSavedColumnPreference(supplier_dashboard_columns);
          this.visible_columns =
            saved_columns && saved_columns !== ''
              ? JSON.parse(saved_columns)
              : this.table_columns;
        } catch (err) {
          this.visible_columns = this.table_columns;
        }

        return this.prepareColumns(this.visible_columns);
      },

      prepareColumns(columnObject: dynamicObj) {
        return Object.entries(columnObject).map(([key, column]) => {
          return {
            name: (column as dynamicObj).name,
            required: true,
            label:
              (column as dynamicObj).translation_key ||
              (column as dynamicObj).label,
            translation_key: (column as dynamicObj).translation_key,
            field: (column as dynamicObj).field,
            actions: true,
            order: (column as dynamicObj).order,
          };
        });
      },

      async getSavedColumnPreference(key: string) {
        const settings_store = useSettingStore();
        const saved_columns = await settings_store.getSetting(key) as dynamicObj;
        return String(!saved_columns ? '' : saved_columns);
      },

      getStatusByValue(value: string) {
        const index = this.supplierStatusList.findIndex(
          (status) => status.value === value,
        );
        if (index > -1) {
           
          return this.supplierStatusList[index].label;
        }
        return value;
      },
    },
  },
);
